#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def isParindrom(l):
    invers = l[::-1]
    if l == invers:
        return True
    return False

def solve(S: str):
    N = len(S)
    if N % 2 == 0:
        print(NO)
        return

    if not isParindrom(S):
        print(NO)
        return 
    
    num = (N - 1) // 2
    p = S[:num]

    if not isParindrom(p):
        print(NO)
        return
    
    num = (N + 3) // 2 - 1
    r = S[num:]

    if not isParindrom(r):
        print(NO)
        return
    
    print(YES)

    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
